insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, auto_check)
select x.id, v.ci, v.ex, v.dn::jsonb, v.ac::jsonb
from (values
(1, 0, 'تقع طبقة الأوزون في الستراتوسفير، على ارتفاع نحو 15–35 km تقريبًا.', '["","التروبوسفير أقرب الطبقات إلى سطح الأرض، وفيها تحدث الظواهر الجوية.","الميزوسفير تعلو الستراتوسفير، وليست موضع طبقة الأوزون.","الثيرموسفير من الطبقات العليا البعيدة عن طبقة الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.088Z"}'::jsonb),
(2, 0, 'جزيء الأوزون $\text{O}_3$ فيه 3 ذرات أكسجين، فعدد الجزيئات $= 6 \div 3 = 2$.', '["","جزيء واحد يحتاج 3 ذرات فقط.","4 جزيئات تحتاج 12 ذرة ($4 \\times 3$)، ولدينا 6 ذرات فقط.","هذا عدد جزيئات الأكسجين $\\text{O}_2$ ($6 \\div 2$)، لا الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(3, 1, 'كل جزيء أوزون $\text{O}_3$ فيه 3 ذرات، فعدد الجزيئات $= 12 \div 3 = 4$.', '["هذا ناتج القسمة على 4 لا على 3.","","هذا ناتج القسمة على 6.","هذا عدد جزيئات $\\text{O}_2$ ($12 \\div 2$)، لا الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(4, 2, 'العالم دوبسون صمم جهازًا لقياس كمية الأوزون، وسُميت وحدة قياسه باسمه (DU).', '["رذرفورد اكتشف النواة بتجربة رقائق الذهب.","كروكس طوّر أنبوب الأشعة المهبطية.","","مليكان قاس شحنة الإلكترون بتجربة قطرة الزيت."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(5, 1, 'المعدل الطبيعي لكمية الأوزون نحو 300 وحدة دوبسون (300 DU)، والانخفاض الكبير عنه يُعد ثقبًا في طبقة الأوزون.', '["150 DU أقل بكثير من المعدل الطبيعي، وتدل على نقص شديد.","","400 DU أعلى من المعدل الطبيعي.","600 DU ضعف المعدل الطبيعي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(6, 1, 'يمتص الأوزون معظم الأشعة فوق البنفسجية الضارة القادمة من الشمس، فيحمي المخلوقات الحية.', '["الأشعة السينية لا تمتصها طبقة الأوزون أساسًا، ويمتصها الغلاف الجوي العلوي.","","الأشعة تحت الحمراء حرارية، وليست ما تحمينا منه طبقة الأوزون.","الضوء المرئي يصل إلى الأرض ولا يُعد ضارًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(7, 0, 'مركبات الكلوروفلوروكربون (CFCs) تتفكك في الستراتوسفير وتطلق الكلور الذي يحطم جزيئات الأوزون.', '["","الأكسجين يكوّن الأوزون ولا يستنزفه.","الأشعة فوق البنفسجية جزء من دورة تكوّن الأوزون الطبيعية، وليست سبب تناقصه.","ثاني أكسيد الكربون من غازات الاحتباس الحراري، ولا يحطم الأوزون."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(8, 0, 'اسمه يدل على مكوناته: كلور (Cl) وفلور (F) وكربون (C).', '["","Ca رمز الكالسيوم لا الكربون.","O رمز الأكسجين، ولا يدخل في تركيبه.","Cr رمز الكروم لا الكربون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(9, 2, 'كل جزيء أوزون $\text{O}_3$ فيه 3 ذرات، فعدد الجزيئات $= 18 \div 3 = 6$.', '["هذا ناتج القسمة على 9.","هذا ناتج القسمة على 6.","","هذا عدد جزيئات $\\text{O}_2$ ($18 \\div 2$)، لا الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(10, 1, 'الكلوروفلوروكربون يستنزف طبقة الأوزون الحامية من الأشعة فوق البنفسجية، ويبقى في الجو مدة طويلة.', '["النيتروجين نحو 78% من الهواء، وهو غاز خامل نسبيًا وغير ضار.","","أول أكسيد الكربون سام عند استنشاقه، لكنه لا يستنزف طبقة الأوزون.","ثاني أكسيد الكربون يسهم في الاحتباس الحراري، لكنه لا يحطم طبقة الأوزون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb)
