insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, auto_check)
select x.id, v.ci, v.ex, v.dn::jsonb, v.ac::jsonb
from (values
(1, 1, 'الكتلة مقياس لكمية المادة في الجسم، ولا تتغير بتغير المكان.', '["الحجم مقدار الحيز الذي يشغله الجسم، لا كمية المادة فيه.","","الكثافة نسبة الكتلة إلى الحجم، لا كمية المادة.","الوزن قوة جذب الجاذبية للكتلة، فيتغير بتغير المكان."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(2, 2, 'المادة كل ما له كتلة ويشغل حيزًا. والحرارة صورة من صور الطاقة، ليس لها كتلة ولا تشغل حيزًا.', '["الماء له كتلة ويشغل حيزًا، فهو مادة.","الهواء خليط غازات له كتلة ويشغل حيزًا، فهو مادة.","","التراب له كتلة ويشغل حيزًا، فهو مادة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(3, 3, 'الدخان جسيمات صلبة دقيقة وغازات، لها كتلة وتشغل حيزًا، فهو مادة.', '["الضوء طاقة لا كتلة لها.","الموجات تنقل الطاقة، وليست مادة.","الحرارة صورة من صور الطاقة.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(4, 3, 'لا يُنصح بلبس العدسات اللاصقة في المختبر، لأن الأبخرة والمواد الكيميائية قد تحتجز بينها وبين العين.', '["لبس معطف المختبر من قواعد السلامة.","لبس القفازات من قواعد السلامة.","لبس نظارات الأمان من قواعد السلامة.",""]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(5, 3, 'الكتلة كمية المادة في الجسم، فلا تتغير بتغير المكان: تبقى $40\,\text{kg}$. الذي يتغير هو الوزن.', '["هذا وزنك على الأرض ($40 \\times 9.8$)، والسؤال عن الكتلة على القمر.","الكيلوجرام وحدة كتلة، لكن الكتلة لا تتضاعف؛ هذا الرقم ناتج ضربها في تسارع الجاذبية الأرضية.","النيوتن وحدة قوة (وزن)، والكتلة تقاس بالكيلوجرام.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(6, 3, 'الهواء خليط غازات له كتلة ويشغل حيزًا، فهو مادة.', '["الضوء طاقة لا كتلة لها.","الحرارة صورة من صور الطاقة.","الصوت موجات تنقل الطاقة عبر الوسط، وليس مادة.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb),
(7, 0, 'الضوء طاقة ليس لها كتلة ولا تشغل حيزًا، فلا يُعد مادة.', '["","الهواء له كتلة ويشغل حيزًا، فهو مادة.","الورق له كتلة ويشغل حيزًا، فهو مادة.","التراب له كتلة ويشغل حيزًا، فهو مادة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.089Z"}'::jsonb)
) as v(number, ci, ex, dn, ac)
