from (values
(1, 2, 'المخلوط مزيج من مادتين نقيتين أو أكثر، تحتفظ كل منهما بخواصها.', '["العنصر مادة نقية من نوع واحد من الذرات.","مكونات المركب تتحد كيميائيًا فتفقد خواصها الأصلية.","","المادة النقية لها تركيب ثابت، وليست مزيجًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.121Z"}'::jsonb),
(2, 0, 'مكونات المخلوط تبقى محتفظة بخواصها، لأنها لم تتحد كيميائيًا.', '["","النسب الثابتة صفة المركب، أما المخلوط فنسبه متغيرة.","المخلوط يتكون بالمزج الفيزيائي لا بالتفاعل.","المخلوط يُفصل بطرق فيزيائية كالترشيح والتقطير."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.121Z"}'::jsonb),
(3, 1, 'المحلول مخلوط متجانس: تركيبه واحد في جميع أجزاء العينة.', '["المخلوط غير المتجانس تختلف مكوناته من جزء لآخر.","","السؤال يصف محلولًا ذائبًا، والمركب لا يتكون بالذوبان بل بالتفاعل.","النظائر ذرات لعنصر واحد تختلف في عدد النيوترونات."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.121Z"}'::jsonb),
