(5, 1, 'مكونات السلطة تُرى منفصلة ومتفاوتة التوزيع، فهي مخلوط غير متجانس.', '["المتجانس تركيبه واحد في كل أجزائه، والسلطة ليست كذلك.","","المحلول مخلوط متجانس.","الغروي جسيماته دقيقة لا تُرى بالعين، ومكونات السلطة كبيرة ظاهرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.121Z"}'::jsonb),
